import numpy as np
from scipy import stats

MAX_DRIVERS = 5

def design(feats):
    # Quick heuristic approach to avoid expensive computations
    # Just use the top features by mean difference and check for strong correlations

    # Calculate mean differences for all features
    mean_diffs = []
    for i, fid in enumerate(feats.ids):
        mean_diff = np.mean(feats.x[feats.y == 1, i]) - np.mean(feats.x[feats.y == 0, i])
        mean_diffs.append((fid, abs(mean_diff)))

    # Sort by magnitude of difference
    mean_diffs.sort(key=lambda x: x[1], reverse=True)

    # Select top features that aren't too correlated with each other
    selected_features = []
    for fid, _ in mean_diffs:
        # Check if this feature is too correlated with already selected ones
        is_duplicate = False
        for sel_fid in selected_features:
            col_a = feats.column(sel_fid)
            col_b = feats.column(fid)
            if abs(np.corrcoef(feats.x[:, col_a], feats.x[:, col_b])[0,1]) > 0.6:
                is_duplicate = True
                break
        if not is_duplicate:
            selected_features.append(fid)
            if len(selected_features) >= MAX_DRIVERS:
                break

    # Simple validation: if we have very few features or they don't show strong differences,
    # return empty design
    if len(selected_features) < 2:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Check if selected features show significant association
    # Just quickly test the first few features
    significant = False
    for fid in selected_features[:3]:  # Test first 3 features
        col_idx = feats.column(fid)
        group0 = feats.x[feats.y == 0, col_idx]
        group1 = feats.x[feats.y == 1, col_idx]
        try:
            t_stat, p_val = stats.ttest_ind(group0, group1, equal_var=False)
            if abs(t_stat) > 3.0 and p_val < 0.001:
                significant = True
                break
        except:
            continue

    if not significant:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Build final design
    drivers = tuple(selected_features[:MAX_DRIVERS])
    columns = tuple(selected_features)

    # Create simple loadings (weight by mean difference)
    loadings = {}
    for fid in selected_features:
        col_idx = feats.column(fid)
        mean_diff = np.mean(feats.x[feats.y == 1, col_idx]) - np.mean(feats.x[feats.y == 0, col_idx])
        loadings[fid] = abs(mean_diff)

    # Normalize loadings
    total_weight = sum(loadings.values())
    if total_weight > 0:
        for fid in loadings:
            loadings[fid] /= total_weight

    # Create products (interactions between top features)
    products = []
    for i, f1 in enumerate(selected_features):
        for j, f2 in enumerate(selected_features[i+1:], i+1):
            products.append((f1, f2))

    return Design(drivers=drivers, columns=columns, products=products, loadings=loadings)
